-- V339: 车间常规尺寸主数据（`shop_standard_sizes`）+ 首版清单
--
-- 背景（LQ 2026-09-24 拍板）：
--   「订做」不是人选的，而是看**盒子尺寸**——车间有这个尺寸的模具就不算订做，没有就算订做。
--   而 ERP 里根本没有这份主数据：packaging_molds / packaging_mold_groups（77 条模具 / 48 组 /
--   37 个口径）全是**气调机的托盒模具**，封口机产线的卷膜/片膜口径一个都没登记；
--   product_variants 的口径列全空；manufacturing_task_config_items 只有产品名称与可选配置。
--
--   → 按 LQ 指示：从库存里「非订做」的名字反推一版常规尺寸，并做成可维护的主数据。
--   完整推导与证据见 docs/车间常规尺寸管理与首版清单-20260924.md。
--
-- 本迁移只做三件事：
--   1. 建表（幂等 CREATE TABLE IF NOT EXISTS）；
--   2. 导入分析产出的首版清单（INSERT IGNORE，绝不覆盖人工后续的增删改）；
--   3. 把气调机的托盒口径从 packaging_mold_groups 一并纳入（INSERT...SELECT，保持同源）。
--
-- ⚠️ 为什么用 INSERT IGNORE 而不是 UPSERT：这是**种子数据**。上线后业务会在管理页停用噪声项
--    （已知噪声：贴体膜/铝箔膜宽度被当成尺寸、模具自身尺寸被当成盒子尺寸），
--    UPSERT 会在补跑时把人工停用又刷回启用。IGNORE 只补缺、不动已有行。

DROP PROCEDURE IF EXISTS v339_create_shop_standard_sizes;
CREATE PROCEDURE v339_create_shop_standard_sizes()
BEGIN
    IF NOT EXISTS (SELECT 1 FROM information_schema.TABLES
                   WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'shop_standard_sizes') THEN
        CREATE TABLE shop_standard_sizes (
            id              BIGINT       NOT NULL AUTO_INCREMENT,
            size_key        VARCHAR(60)  NOT NULL COMMENT '规范化尺寸键：RECT:<小>x<大> / ROUND:<直径> / RECT:<四位业务简写>',
            shape_type      VARCHAR(10)  NOT NULL COMMENT 'RECT=方盒 / ROUND=圆口径',
            length_mm       VARCHAR(40)  NULL COMMENT '方盒长（大值）',
            width_mm        VARCHAR(40)  NULL COMMENT '方盒宽（小值）',
            diameter_mm     VARCHAR(40)  NULL COMMENT '圆口径直径',
            shorthand       VARCHAR(20)  NULL COMMENT '压掉乘号的业务简写原文（2014=141.2x201.4、2216=224.6x160.9…）',
            workshop_name   VARCHAR(100) NULL COMMENT '归属车间；NULL=全厂通用（当前一律 NULL：模具是物理实体，哪条线都能用）',
            observed_line   VARCHAR(100) NULL COMMENT '分析推断的主要产线，仅作评审参考，不参与判定',
            evidence_names  INT          NOT NULL DEFAULT 0 COMMENT '该尺寸出现在多少个不同的非订做库存名里（证据强度）',
            evidence_orders INT          NOT NULL DEFAULT 0 COMMENT '任务单里用过该尺寸的单数（证据强度）',
            source          VARCHAR(20)  NOT NULL DEFAULT 'MANUAL' COMMENT 'MINED=库存反推导入 / MANUAL=人工新增',
            active          TINYINT(1)   NOT NULL DEFAULT 1 COMMENT '1 启用（判为常规尺寸）/ 0 停用（判为订做）',
            remark          VARCHAR(500) NULL,
            created_at      DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
            updated_at      DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
            PRIMARY KEY (id),
            UNIQUE KEY uk_shop_standard_size_key (size_key),
            KEY idx_shop_standard_size_active (active),
            KEY idx_shop_standard_size_workshop (workshop_name)
        ) COMMENT='车间常规尺寸：建单时按盒子尺寸比对判定「订做/常规」的判据表';
    END IF;
END;
CALL v339_create_shop_standard_sizes();
DROP PROCEDURE IF EXISTS v339_create_shop_standard_sizes;

