-- ============================================================
-- 3. 气调机托盒口径：直接取自模具主数据，保持同源（不手抄）
--    键与上面同一形态（RECT:<小>x<大> / ROUND:<直径>），小数按 stripTrailingZeros 口径去尾零
-- ============================================================
INSERT IGNORE INTO shop_standard_sizes
  (size_key, shape_type, length_mm, width_mm, diameter_mm, shorthand,
   workshop_name, observed_line, evidence_names, evidence_orders, source, active, remark)
SELECT CONCAT('RECT:',
              TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST(LEAST(g.length_mm + 0, g.width_mm + 0) AS DECIMAL(12,3)))),
              'x',
              TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST(GREATEST(g.length_mm + 0, g.width_mm + 0) AS DECIMAL(12,3))))),
       'RECT',
       TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST(GREATEST(g.length_mm + 0, g.width_mm + 0) AS DECIMAL(12,3)))),
       TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST(LEAST(g.length_mm + 0, g.width_mm + 0) AS DECIMAL(12,3)))),
       NULL, NULL, NULL, NULL, 0, 0, 'MINED', 1,
       CONCAT('气调机托盒模具口径（来源 packaging_mold_groups #', g.id, '：', g.name, '）')
FROM packaging_mold_groups g
WHERE g.deleted_at IS NULL AND g.shape_type = 'square' AND g.length_mm IS NOT NULL AND g.width_mm IS NOT NULL;

INSERT IGNORE INTO shop_standard_sizes
  (size_key, shape_type, length_mm, width_mm, diameter_mm, shorthand,
   workshop_name, observed_line, evidence_names, evidence_orders, source, active, remark)
SELECT CONCAT('ROUND:',
              TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST(g.diameter_mm + 0 AS DECIMAL(12,3))))),
       'ROUND', NULL, NULL,
       TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST(g.diameter_mm + 0 AS DECIMAL(12,3)))),
       NULL, NULL, NULL, 0, 0, 'MINED', 1,
       CONCAT('气调机托盒模具口径（来源 packaging_mold_groups #', g.id, '：', g.name, '）')
FROM packaging_mold_groups g
WHERE g.deleted_at IS NULL AND g.shape_type = 'round' AND g.diameter_mm IS NOT NULL;
